window.AUTH=window.AUTH||{};window.AUTH["10-577"]={"d":"10-577","id":"2011/10-577","n":"Kawashima v. Holder","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/196786/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/kawashima-v-holder-brief-merits","n":103}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep565/usrep565478/usrep565478.pdf","tr":true,"items":[{"t":"case","label":"Amos v. Commissioner","cite":"43 T.C. 56","y":1964,"url":"https://www.courtlistener.com/c/T.C./43/56/","by":{"0":"30"}},{"t":"case","label":"Arguelles-Olivares v. Mukasey","cite":"526 F.3d 171","y":2008,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/526/171/","sum":"Noting that alien did “not contest that his conviction under [Section 7206(1)] ‘involves fraud or deceit’ within the meaning of the removability provision”.","sumSrc":"brief:0","by":{"0":"19, 36"}},{"t":"case","label":"Babbitt v. Sweet Home Chapter","cite":"515 U.S. 687","y":1995,"id":"1994/94-859","sc":1,"sum":"The Supreme Court held that habitat modification is a legitimate application of the word \"harm.\" First, the Court found that the Court of Appeals was incorrect in assuming that the words in the definition of \"take\" only apply to actions involving direct contact with endangered animals.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Bloate v. United States","cite":"130 S. Ct. 1345","y":2010,"id":"2009/08-728","sc":1,"sum":"The Court held that the time granted to prepare pretrial motions is not automatically granted exclusion from the Speedy Trial Act's 70-day time limit.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Boulware v. United States","cite":"552 U.S. 421","y":2008,"id":"2007/06-1509","sc":1,"op":2,"sum":"The Court held that a defendant in a criminal tax case does not need to show a contemporaneous intent to treat diversions as returns of capital to demonstrate no taxes were owed. All that mattered, according to the Court, was whether the corporation had earnings or profits and the taxpayer's basis for his stock.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"131 S. Ct. 1068","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Carachuri-Rosendo v. Holder","cite":"130 S. Ct. 2577","y":2010,"id":"2009/09-60","sc":1,"sum":"The Court held that a minor drug offense is not automatic grounds for deportation of a legal immigrant.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 29, 37"}},{"t":"case","label":"Corley v. United States","cite":"129 S. Ct. 1558","y":2009,"id":"2008/07-10441","sc":1,"op":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"DePierre v. United States","cite":"131 S. Ct. 2225","y":2011,"id":"2010/09-1533","sc":1,"sum":"The Court held that the term \"cocaine base\" encompasses every form of cocaine that is classified chemically as a base.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"D. Ginsberg & Sons, Inc. v. Popkin","cite":"285 U.S. 204","y":1932,"id":"scdb/1931-109","sc":1,"op":2,"sum":"A court of bankruptcy has no authority under § 2 (15) of the Bankruptcy Act or § 261 of the Judicial Code to issue a writ of ne exeat against an absconding officer of a bankrupt corporation to the end that he may be examined in the bankruptcy proceedings. P. 206. 50 F. (2d) 693, affirmed. CERTIORARI, 284 U. S. 609, to review the reversal of an order sustaining the issuance of a writ of ne exeat in bankruptcy …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Dolan v. United States Postal Serv.","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Gutierrez de Martinez v. Lamagno","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"HCSC-Laundry v. United States","cite":"450 U.S. 1","y":1981,"id":"1980/80-338","sc":1,"ar":1,"sum":"A cooperative hospital service organization cannot qualify for exemption from federal income taxation as a charitable organization under § 501 (c)(3) of the Internal Revenue Code of 1954, but instead may qualify only if it performs one of the services listed in § 501 (e) (1) (A). This conclusion is supported both by the principle of statutory construction that a specific statute, here subsection (e), controls over a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 25"}},{"t":"case","label":"INS v. Aguirre-Aguirre","cite":"526 U.S. 415","y":1999,"id":"1998/97-1754","sc":1,"sum":"The Court noted that withholding of deportation is mandatory if an alien establishes that it is more likely than not that he or she will suffer political persecution if deported.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":3,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"22, 36"}},{"t":"case","label":"Jordan v. De George","cite":"341 U.S. 223","y":1951,"id":"scdb/1950-070","sc":1,"sum":"Conspiracy to defraud the United States of taxes on distilled spirits is a \"crime involving moral turpitude\" within the meaning of § 19 (a) of the Immigration Act of 1917, 8 U. S. C. § 155 (a), which requires the deportation of any alien who is sentenced more than once to imprisonment for one year or more because of conviction in this country of any such crime.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"0":"15, 41"}},{"t":"case","label":"Ki Se Lee v. Ashcroft","cite":"368 F.3d 218","y":2004,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/368/218/","by":{"0":"9, 19, 32, 35, 36"}},{"t":"case","label":"Klein v. Commissioner","cite":"880 F.2d 260","y":1989,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/880/260/","op":1,"by":{"0":"30"}},{"t":"case","label":"Lamie v. United States Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Leocal v. Ashcroft","cite":"543 U.S. 1","y":2004,"id":"2004/03-583","sc":1,"op":1,"ar":1,"sum":"The Court held that state DUI offenses, except when involving purposeful intent, are accidental and not crimes of violence under federal law. Le therefore did not commit an aggravated felony for which he could be deported.","sumSrc":"Oyez","by":{"0":"31, 41"}},{"t":"case","label":"Microsoft Corp. v. i4i Ltd. P’ship","cite":"131 S. Ct. 2238","y":2011,"id":"2010/10-290","sc":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"0":"22, 29"}},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"sum":"A person who receives genuine vehicle titles, knowing that they incorporate fraudulently tendered odometer readings, receives those titles knowing them to have been \"falsely made\" in violation of § 2314.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"Muscarello v. United States","cite":"524 U.S. 125","y":1998,"id":"1997/96-1654","sc":1,"sum":"The Court held that the phrase \"carries a firearm\" applies to a person who knowingly possesses and conveys firearms in a vehicle, including in the locked glove compartment or trunk of a car, which the person accompanies.","sumSrc":"Oyez","by":{"0":"15, 41"}},{"t":"case","label":"National Cable & Telecomms. Ass’n v. Brand X Internet Servs.","cite":"545 U.S. 967","y":2005,"id":"2004/04-277","sc":1,"sum":"The Court held that the FCC lawfully construed the Communications Act to not define cable broadband providers as \"telecommunications services.\" The Court held that the Ninth Circuit should have followed the Supreme Court's 1984 decision in Chevron v. Natural Resources Defense Council.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"National Cable & Telecomms. Ass’n, Inc. v. Gulf Power Co.","cite":"534 U.S. 327","y":2002,"id":"2001/00-832","sc":1,"op":1,"sum":"The Court held 6-2 that the Act covers attachments that provide high-speed Internet access at the same time as cable television and 8-0 that the Act applies to wireless attachments by providers of wireless telecommunications services.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Navarro-Lopez v. Gonzales","cite":"503 F.3d 1063","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/503/1063/","by":{"0":"10"}},{"t":"case","label":"Negusie v. Holder","cite":"129 S. Ct. 1159","y":2009,"id":"2008/07-499","sc":1,"sum":"The Court held that the Board of Immigration Appeals (BIA) incorrectly interpreted provisions of the Immigration and Nationality Act (INA) from a mistaken legal premise.","sumSrc":"Oyez","by":{"0":"16, 43"}},{"t":"case","label":"Nijhawan v. Attorney Gen.","cite":"523 F.3d 387","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/523/387/","by":{"0":"40"}},{"t":"case","label":"Nijhawan v. Holder","cite":"129 S. Ct. 2294","y":2009,"id":"2008/08-495","sc":1,"sum":"The Court found that when an alien is convicted of conspiracy and held responsible for causing more than $10,000 in damages, the statute requirement used by the Immigration and Nationality Act (INA) to deport the alien is satisfied, even if the $10,000 is not established by a jury.","sumSrc":"Oyez","by":{"0":"9, 10, 17, 26, 27, 40, 41"}},{"t":"case","label":"Nijhawan v. Mukasey","cite":"129 S. Ct. 988","y":2009,"url":"https://www.courtlistener.com/c/S.%20Ct./129/988/","sc":1,"sum":"Finding statutory provision ambiguous, but remanding to the Board for it to address the question in the first instance, rather than adopting the narrowing construction offered by the alien.","sumSrc":"brief:0","by":{"0":"10"}},{"t":"case","label":"Padilla v. Kentucky","cite":"130 S. Ct. 1473","y":2010,"id":"2009/08-651","sc":1,"op":1,"ar":1,"sum":"The Court held that counsel must inform a client whether or not his plea carries a risk of deportation under the Sixth Amendment.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"sum":"The time respondent spent at the treatment center while \"released\" on bail was not \"official detention\" within the meaning of §3585(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 40"}},{"t":"case","label":"Sansone v. United States","cite":"380 U.S. 343","y":1965,"id":"1964/365","sc":1,"op":2,"sum":"Petitioner was indicted for willfully attempting to evade federal income taxes in violation of 26 U. S. C. § 7201. At the end of his trial he requested that the jury be instructed that it could acquit him of that offense, a felony, but could convict him of the lesserincluded misdemeanors of willfully filing a fraudulent or false return in violation of § 7207, or willfully failing to pay his taxes when due in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Spies v. United States","cite":"317 U.S. 492","y":1943,"id":"scdb/1942-089","sc":1,"op":2,"ar":1,"sum":"Section 145 (b) of the Internal Revenue Code, making it a felony willfully to attempt to evade or defeat a tax, is not violated by willful omissions to make a return and pay a tax, defined in § 145 (a) as misdemeanors. P. 497. 128 F. 2d 743, reversed.. CERTIORARI, post, p. 610, to review the affirmance of a conviction upon an indictment under 26 U. S. C. § 145 (b) for attempting to evade and defeat a federal income …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15, 33"}},{"t":"case","label":"Sykes v. United States","cite":"131 S. Ct. 2267","y":2011,"id":"2010/09-11311","sc":1,"sum":"The Court held that a conviction for resisting arrest counts as a violent felony under the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"United States v. Cheek","cite":"498 U.S. 192","y":1991,"id":"1990/89-658","sc":1,"sum":"Petitioner Cheek was charged with six counts of willfully failing to file a federal income tax return in violation of § 7203 of the Internal Revenue Code (Code) and three counts of willfully attempting to evade his income taxes in violation of §7201. Although admitting that he had not filed his returns, he testified that he had not acted willfully because he sincerely believed, based on his indoctrination by a group …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"United States v. Hayes","cite":"129 S. Ct. 1079","y":2009,"id":"2008/07-608","sc":1,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Klein","cite":"247 F.2d 908","y":1957,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/247/908/","by":{"0":"28"}},{"t":"case","label":"United States v. O’Hagan","cite":"521 U.S. 642","y":1997,"id":"1996/96-842","sc":1,"sum":"The Court ruled that a security-trader who fails to disclose personal profits gained from reliance on exclusive information is guilty of employing \"a deceptive device...in connection with the purchase of a security.\" The security-trader knowingly abuses the duty owed toward the source of information, whether the source is the company he works for or not.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"United States v. Pollen","cite":"978 F.2d 78","y":1992,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/978/78/","sum":"Describing two counts of indictment charging defendant with “knowingly and willfully attempt[ing] to evade the payment of * * * federal income taxes * * * by ‘placing part of his assets out of reach of the United States Government’ by causing” gold to be brought to a bank in Canada to be transferred to an account in Switzerland.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"United States v. Scharton","cite":"285 U.S. 518","y":1932,"id":"scdb/1931-055","sc":1,"op":7,"ar":5,"sum":"Section 1110 (a) of the Revenue Act of 1926 sets a general limitation of three years upon the prosecution of \" any of the various offenses arising under the internal revenue laws... Provided, That for offenses involving the defrauding or attempting to defraud the United States... in any manner, the period of limitation shall be six years....\"","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 32, 33"}},{"t":"case","label":"United States v. Trownsell","cite":"367 F.2d 815","y":1966,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/367/815/","by":{"0":"34"}},{"t":"case","label":"Valansi v. Ashcroft","cite":"278 F.3d 203","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/278/203/","by":{"0":"39"}},{"t":"case","label":"Varity Corp. v. Howe","cite":"516 U.S. 489","y":1996,"id":"1995/94-1471","sc":1,"sum":"The Court held that, under the specific factual circumstances, Varity and Massey-Ferguson acted in their capacity as an ERISA fiduciary when they significantly and deliberately misled the plan's beneficiaries, thereby violating their fiduciary obligations imposed by ERISA.","sumSrc":"Oyez","by":{"0":"22, 23, 29"}},{"t":"case","label":"Wright v. Commissioner","cite":"84 T.C. 636","y":1985,"url":"https://www.courtlistener.com/c/T.C./84/636/","by":{"0":"13, 20, 30"}},{"t":"law","label":"Pub. L. No. 100-690","url":"https://www.govinfo.gov/link/statute/102/4469","by":{"0":"2"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)","(c)(2)"],"by":{"0":"42, 41"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 101-649","url":"https://www.govinfo.gov/link/statute/104/5048","by":{"0":"3"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)(1988)","(a)(43)","(a)(43)(A)","(a)(43)(E)","(a)(43)(F)","(a)(43)(G)","(a)(43)(I)","(a)(43)(J)","(a)(43)(K)","(a)(43)(M)(1994)","(a)(43)(M)","(a)(43)(M)(i)","(a)(43)(M)(ii)","(a)(43)(P)","(a)(43)(R)","(a)(43)(S)","(h)(2)","(h)(3)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":7,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 2, 3, 36, 36, 25, 3, 36, 37, 3, 37, 39, 3, 39, 39, 3, 41, passim, passim, 3, 3, 26, 3, 26, 31, 31"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(b)(2)(A)(ii)","(b)(2)(B)(i)"],"by":{"0":"4, 4"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(9)(A)(iii)"],"by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)(2)(A)(iii)"],"stext":{"head":"§1227. Deportable aliens","paras":[[0,"(a) Classes of deportable aliens"],[0,"Any alien (including an alien crewman) in and admitted to the United States shall, upon the order of the Attorney General, be removed if the alien is within one or more of the following classes of deportable aliens:"],[0,"(1) Inadmissible at time of entry or of adjustment of status or violates status"],[0,"(A) Inadmissible aliens"],[2,"Any alien who at the time of entry or adjustment of status was within one or more of the classes of aliens inadmissible by the law existing at such time is deportable."],[0,"(B) Present in violation of law"],[2,"Any alien who is present in the United States in violation of this chapter or any other law of the United States, or whose nonimmigrant visa (or other documentation authorizing admission into the United States as a nonimmigrant) has been revoked under section 1201(i) of this title, is deportable."],[0,"(C) Violated nonimmigrant status or condition of entry"],[0,"(i) Nonimmigrant status violators"],[3,"Any alien who was admitted as a nonimmigrant and who has failed to maintain the nonimmigrant status in which the alien was admitted or to which it was changed under section 1258 of this title, or to comply with the conditions of any such status, is deportable."],[0,"(ii) Violators of conditions of entry"],[3,"Any alien whom the Secretary of Health and Human Services certifies has failed to comply with terms, conditions, and controls that were imposed under section 1182(g) of this title is deportable."],[0,"(D) Termination of conditional permanent residence"],[0,"(i) In general"],[3,"Any alien with permanent resident status on a conditional basis under section 1186a of this title (relating to conditional permanent resident status for certain alien spouses and sons and daughters) or under section 1186b of this title (relating to conditional permanent resident status for certain alien entrepreneurs, spouses, and children) who has had such status terminated under such respective section is deportable."],[0,"(ii) Exception"],[3,"Clause (i) shall not apply in the cases described in section 1186a(c)(4) of this title (relating to certain hardship waivers)."],[0,"(E) Smuggling"],[0,"(i) In general"],[3,"Any alien who (prior to the date of entry, at the time of any entry, or within 5 years of the date of any entry) knowingly has encouraged, induced, assisted, abetted, or aided any other alien to enter or to try to enter the United States in violation of law is deportable."],[0,"(ii) Special rule in the case of family reunification"],[3,"Clause (i) shall not apply in the case of alien who is an eligible immigrant (as defined in section 301(b)(1) of the Immigration Act of 1990), was physically present in the United States on May 5, 1988, and is seeking admission as an immediate relative or under section 1153(a)(2) of this title (including under section 112 of the Immigration Act of 1990) or benefits under section 301(a) of the Immigration Act of 1990 if the alien, before May 5, 1988, has encouraged, induced, assisted, abetted, or aided only the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(iii) Waiver authorized"],[3,"The Attorney General may, in his discretion for humanitarian purposes, to assure family unity, or when it is otherwise in the public interest, waive application of clause (i) in the case of any alien lawfully admitted for permanent residence if the alien has encouraged, induced, assisted, abetted, or aided only an individual who at the time of the offense was the alien's spouse, parent, son, or daughter (and no other individual) to enter the United States in violation of law."],[0,"(F) Repealed. Pub. L. 104–208, div. C, title VI, §671(d)(1)(C), Sept. 30, 1996, 110 Stat. 3009–723"],[0,"(G) Marriage fraud"],[2,"An alien shall be considered to be deportable as having procured a visa or other documentation by fraud (within the meaning of section 1182(a)(6)(C)(i) of this title) and to be in the United States in violation of this chapter (within the meaning of subparagraph (B)) if—"],[3,"(i) the alien obtains any admission into the United States with an immigrant visa or other documentation procured on the basis of a marriage entered into less than 2 years prior to such admission of the alien and which, within 2 years subsequent to any admission of the alien in the United States, shall be judicially annulled or terminated, unless the alien establishes to the satisfaction of the Attorney General that such marriage was not contracted for the purpose of evading any provisions of the immigration laws, or"],[3,"(ii) it appears to the satisfaction of the Attorney General that the alien has failed or refused to fulfill the alien's marital agreement which in the opinion of the Attorney General was made for the purpose of procuring the alien's admission as an immigrant."],[0,"(H) Waiver authorized for certain misrepresentations"],[2,"The provisions of this paragraph relating to the removal of aliens within the United States on the ground that they were inadmissible at the time of admission as aliens described in section 1182(a)(6)(C)(i) of this title, whether willful or innocent, may, in the discretion of the Attorney General, be waived for any alien (other than an alien described in paragraph (4)(D)) who—"],[3,"(i)(I) is the spouse, parent, son, or daughter of a citizen of the United States or of an alien lawfully admitted to the United States for permanent residence; and"],[3,"(II) was in possession of an immigrant visa or equivalent document and was otherwise admissible to the United States at the time of such admission except for those grounds of inadmissibility specified under paragraphs (5)(A) and (7)(A) of section 1182(a) of this title which were a direct result of that fraud or misrepresentation."],[3,"(ii) is a VAWA self-petitioner."],[2,"A waiver of removal for fraud or misrepresentation granted under this subparagraph shall also operate to waive removal based on the grounds of inadmissibility directly resulting from such fraud or misrepresentation."],[0,"(2) Criminal offenses"],[0,"(A) General crimes"],[0,"(i) Crimes of moral turpitude"],[3,"Any alien who—"],[4,"(I) is convicted of a crime involving moral turpitude committed within five years (or 10 years in the case of an alien provided lawful permanent resident status under section 1255(j) of this title) after the date of admission, and"],[4,"(II) is convicted of a crime for which a sentence of one year or longer may be imposed,"],[0,"is deportable."],[0,"(ii) Multiple criminal convictions"],[3,"Any alien who at any time after admission is convicted of two or more crimes involving moral turpitude, not arising out of a single scheme of criminal misconduct, regardless of whether confined therefor and regardless of whether the convictions were in a single trial, is deportable."],[0,"(iii) Aggravated felony"],[3,"Any alien who is convicted of an aggravated felony at any time after admission is deportable."],[0,"(iv) High speed flight"],[3,"Any alien who is convicted of a violation of section 758 of title 18 (relating to high speed flight from an immigration checkpoint) is deportable."],[0,"(v) Failure to register as a sex offender"],[3,"Any alien who is convicted under section 2250 of title 18 is deportable."],[0,"(vi) Waiver authorized"],[3,"Clauses (i), (ii), (iii), and (iv) shall not apply in the case of an alien with respect to a criminal conviction if the alien subsequent to the criminal conviction has been granted a full and unconditional pardon by the President of the United States or by the Governor of any of the several States."],[0,"(B) Controlled substances"],[0,"(i) Conviction"],[3,"Any alien who at any time after admission has been convicted of a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21), other than a single offense involving possession for one's own use of 30 grams or less of marijuana, is deportable."],[0,"(ii) Drug abusers and addicts"],[3,"Any alien who is, or at any time after admission has been, a drug abuser or addict is deportable."],[0,"(C) Certain firearm offenses"],[2,"Any alien who at any time after admission is convicted under any law of purchasing, selling, offering for sale, exchanging, using, owning, possessing, or carrying, or of attempting or conspiring to purchase, sell, offer for sale, exchange, use, own, possess, or carry, any weapon, part, or accessory which is a firearm or destructive device (as defined in section 921(a) of title 18) in violation of any law is deportable."],[0,"(D) Miscellaneous crimes"],[2,"Any alien who at any time has been convicted (the judgment on such conviction becoming final) of, or has been so convicted of a conspiracy or attempt to violate—"],[3,"(i) any offense under chapter 37 (relating to espionage), chapter 105 (relating to sabotage), or chapter 115 (relating to treason and sedition) of title 18 for which a term of imprisonment of five or more years may be imposed;"],[3,"(ii) any offense under section 871 or 960 of title 18;"],[3,"(iii) a violation of any provision of the Military Selective Service Act (50 U.S.C. App. 451 et seq.) [now 50 U.S.C. 3801 et seq.] or the Trading With the Enemy Act (50 U.S.C. App. 1 et seq.) [now 50 U.S.C. 4301 et seq.]; or"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1227?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1227. Deportable aliens","tname":"Aliens and Nationality","by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1227b","url":"https://www.law.cornell.edu/uscode/text/8/1227b","subs":["(a)(3)","(b)(1)(c)"],"by":{"0":"4, 4"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(c)(3)(A)"],"by":{"0":"17"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)(3)"],"by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1229c","url":"https://www.law.cornell.edu/uscode/text/8/1229c","subs":["(b)(1)(C)"],"by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(3)(B)(ii)"],"by":{"0":"4"}},{"t":"usc","label":"8 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/8/1251","subs":["(a)(4)(B)(1988)"],"by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(b)(4)(A)"],"by":{"0":"7"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","by":{"0":"41"}},{"t":"law","label":"Pub. L. No. 103-416","url":"https://www.govinfo.gov/link/statute/108/4305","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/18/16","by":{"0":"36, 41"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","stext":{"head":"§371. Conspiracy to commit offense or to defraud United States","paras":[[0,"If two or more persons conspire either to commit any offense against the United States, or to defraud the United States, or any agency thereof in any manner or for any purpose, and one or more of such persons do any act to effect the object of the conspiracy, each shall be fined under this title or imprisoned not more than five years, or both."],[0,"If, however, the offense, the commission of which is the object of the conspiracy, is a misdemeanor only, the punishment for such conspiracy shall not exceed the maximum punishment provided for such misdemeanor."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/371?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§371. Conspiracy to commit offense or to defraud United States","tname":"Crimes and Criminal Procedure","by":{"0":"33"}},{"t":"usc","label":"18 U.S.C. § 585","url":"https://www.law.cornell.edu/uscode/text/18/585","op":1,"tname":"Crimes and Criminal Procedure","by":{"0":"33"}},{"t":"usc","label":"26 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/26/501","subs":["(c)(3)"],"by":{"0":"25"}},{"t":"usc","label":"26 U.S.C. § 1266","url":"https://www.law.cornell.edu/uscode/text/26/1266","by":{"0":"32"}},{"t":"usc","label":"26 U.S.C. § 6531","url":"https://www.law.cornell.edu/uscode/text/26/6531","subs":["(1)","(2)"],"stext":{"head":"§6531. Periods of limitation on criminal prosecutions","paras":[[0,"No person shall be prosecuted, tried, or punished for any of the various offenses arising under the internal revenue laws unless the indictment is found or the information instituted within 3 years next after the commission of the offense, except that the period of limitation shall be 6 years—"],[1,"(1) for offenses involving the defrauding or attempting to defraud the United States or any agency thereof, whether by conspiracy or not, and in any manner;"],[1,"(2) for the offense of willfully attempting in any manner to evade or defeat any tax or the payment thereof;"],[1,"(3) for the offense of willfully aiding or assisting in, or procuring, counseling, or advising, the preparation or presentation under, or in connection with any matter arising under, the internal revenue laws, of a false or fraudulent return, affidavit, claim, or document (whether or not such falsity or fraud is with the knowledge or consent of the person authorized or required to present such return, affidavit, claim, or document);"],[1,"(4) for the offense of willfully failing to pay any tax, or make any return (other than a return required under authority of part III of subchapter A of chapter 61) at the time or times required by law or regulations;"],[1,"(5) for offenses described in sections 7206(1) and 7207 (relating to false statements and fraudulent documents);"],[1,"(6) for the offense described in section 7212(a) (relating to intimidation of officers and employees of the United States);"],[1,"(7) for offenses described in section 7214(a) committed by officers and employees of the United States; and"],[1,"(8) for offenses arising under section 371 of Title 18 of the United States Code, where the object of the conspiracy is to attempt in any manner to evade or defeat any tax or the payment thereof."],[0,"The time during which the person committing any of the various offenses arising under the internal revenue laws is outside the United States or is a fugitive from justice within the meaning of section 3290 of Title 18 of the United States Code, shall not be taken as any part of the time limited by law for the commencement of such proceedings. (The preceding sentence shall also be deemed an amendment to section 3748(a) of the Internal Revenue Code of 1939, and shall apply in lieu of the sentence in section 3748(a) which relates to the time during which a person committing an offense is absent from the district wherein the same is committed, except that such amendment shall apply only if the period of limitations under section 3748 would, without the application of such amendment, expire more than 3 years after the date of enactment of this title, and except that such period shall not, with the application of this amendment, expire prior to the date which is 3 years after the date of enactment of this title.) Where a complaint is instituted before a commissioner of the United States within the period above limited, the time shall be extended until the date which is 9 months after the date of the making of the complaint before the commissioner of the United States. For the purpose of determining the periods of limitation on criminal prosecutions, the rules of section 6513 shall be applicable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6531?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§6531. Periods of limitation on criminal prosecutions","tname":"Internal Revenue Code","by":{"0":"33, 33, 33"}},{"t":"usc","label":"26 U.S.C. § 6653","url":"https://www.law.cornell.edu/uscode/text/26/6653","subs":["(1988)","(b)(1)(1982)"],"by":{"0":"30, 20"}},{"t":"usc","label":"26 U.S.C. § 6663","url":"https://www.law.cornell.edu/uscode/text/26/6663","stext":{"head":"§6663. Imposition of fraud penalty","paras":[[0,"(a) Imposition of penalty"],[0,"If any part of any underpayment of tax required to be shown on a return is due to fraud, there shall be added to the tax an amount equal to 75 percent of the portion of the underpayment which is attributable to fraud."],[0,"(b) Determination of portion attributable to fraud"],[0,"If the Secretary establishes that any portion of an underpayment is attributable to fraud, the entire underpayment shall be treated as attributable to fraud, except with respect to any portion of the underpayment which the taxpayer establishes (by a preponderance of the evidence) is not attributable to fraud."],[0,"(c) Special rule for joint returns"],[0,"In the case of a joint return, this section shall not apply with respect to a spouse unless some part of the underpayment is due to the fraud of such spouse."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6663?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6663. Imposition of fraud penalty","tname":"Internal Revenue Code","by":{"0":"5"}},{"t":"usc","label":"26 U.S.C. § 7201","url":"https://www.law.cornell.edu/uscode/text/26/7201","stext":{"head":"§7201. Attempt to evade or defeat tax","paras":[[0,"Any person who willfully attempts in any manner to evade or defeat any tax imposed by this title or the payment thereof shall, in addition to other penalties provided by law, be guilty of a felony and, upon conviction thereof, shall be fined not more than $100,000 ($500,000 in the case of a corporation), or imprisoned not more than 5 years, or both, together with the costs of prosecution."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7201?type=usc&year=mostrecent&link-type=html"},"op":31,"ar":2,"head":"§7201. Attempt to evade or defeat tax","tname":"Internal Revenue Code","by":{"0":"5"}},{"t":"usc","label":"26 U.S.C. § 7206","url":"https://www.law.cornell.edu/uscode/text/26/7206","subs":["(1)","(2)"],"stext":{"head":"§7206. Fraud and false statements","paras":[[0,"Any person who—"],[0,"(1) Declaration under penalties of perjury"],[1,"Willfully makes and subscribes any return, statement, or other document, which contains or is verified by a written declaration that it is made under the penalties of perjury, and which he does not believe to be true and correct as to every material matter; or"],[0,"(2) Aid or assistance"],[1,"Willfully aids or assists in, or procures, counsels, or advises the preparation or presentation under, or in connection with any matter arising under, the internal revenue laws, of a return, affidavit, claim, or other document, which is fraudulent or is false as to any material matter, whether or not such falsity or fraud is with the knowledge or consent of the person authorized or required to present such return, affidavit, claim, or document; or"],[0,"(3) Fraudulent bonds, permits, and entries"],[1,"Simulates or falsely or fraudulently executes or signs any bond, permit, entry, or other document required by the provisions of the internal revenue laws, or by any regulation made in pursuance thereof, or procures the same to be falsely or fraudulently executed, or advises, aids in, or connives at such execution thereof; or"],[0,"(4) Removal or concealment with intent to defraud"],[1,"Removes, deposits, or conceals, or is concerned in removing, depositing, or concealing, any goods or commodities for or in respect whereof any tax is or shall be imposed, or any property upon which levy is authorized by section 6331, with intent to evade or defeat the assessment or collection of any tax imposed by this title; or"],[0,"(5) Compromises and closing agreements"],[1,"In connection with any compromise under section 7122, or offer of such compromise, or in connection with any closing agreement under section 7121, or offer to enter into any such agreement, willfully—"],[0,"(A) Concealment of property"],[2,"Conceals from any officer or employee of the United States any property belonging to the estate of a taxpayer or other person liable in respect of the tax, or"],[0,"(B) Withholding, falsifying, and destroying records"],[2,"Receives, withholds, destroys, mutilates, or falsifies any book, document, or record, or makes any false statement, relating to the estate or financial condition of the taxpayer or other person liable in respect of the tax;"],[0,"shall be guilty of a felony and, upon conviction thereof, shall be fined not more than $100,000 ($500,000 in the case of a corporation), or imprisoned not more than 3 years, or both, together with the costs of prosecution."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7206?type=usc&year=mostrecent&link-type=html"},"op":13,"ar":1,"head":"§7206. Fraud and false statements","tname":"Internal Revenue Code","by":{"0":"5, passim, passim"}}]};